using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>().ToContainer("Products");

        // EF Core 9: Discriminator property renamed to "$type" by default.
        // Existing 500K documents use "Discriminator" — preserve for compatibility.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // EF Core 9: id no longer includes discriminator (was "Product|123", now "123").
        // Existing documents have compound ids — preserve old format.
        modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);

        // EF Core 9: HasIndex now throws for Cosmos entities.
        // Removed — manage indexing via Azure Portal/Bicep/Terraform instead.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } = null!; }

